// Regenerates populated.sql from the real v0.1.0 storage code:
//   git worktree add --detach /tmp/dq010 v0.1.0
//   node tests/fixtures/v0.1.0/generate.ts /tmp/dq010/src tests/fixtures/v0.1.0/populated.sql
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { DatabaseSync } from "node:sqlite";

const [srcRoot, out] = process.argv.slice(2);
if (!srcRoot || !out) throw new Error("usage: generate.ts <v0.1.0 src dir> <out.sql>");

type Session = { handle(req: { id: string; op: string; payload: unknown }): unknown };
const mod = (await import(pathToFileURL(resolve(srcRoot, "storage/session.ts")).href)) as {
  createStorageSession(emit: () => void, now: () => number): Session;
};

const T0 = 1_700_000_000_000;
let now = T0;
const session = mod.createStorageSession(
  () => undefined,
  () => now,
);
const dir = mkdtempSync(join(tmpdir(), "dq010-"));
const dbPath = join(dir, "v010.db");
let seq = 0;
const call = <T>(op: string, payload: unknown): T =>
  session.handle({ id: String(++seq), op, payload }) as T;
const add = (name: string, data: unknown, extra: Record<string, unknown> = {}) =>
  call<{ row: { id: string } }>("enqueue", {
    nowMs: now,
    queue: "app",
    name,
    payloadJson: JSON.stringify(data),
    maxAttempts: 3,
    delayMs: 0,
    priority: 0,
    dedupeKey: null,
    attemptTimeoutMs: null,
    backoff: { type: "none" },
    ...extra,
  }).row;
const claim = (name: string, leaseDurationMs = 60 * 60 * 1000) =>
  call<{ id: string; lease_generation: number }>("claim", {
    nowMs: now,
    queue: "app",
    workerId: "w-old",
    names: [name],
    leaseDurationMs,
  });

call("init", { path: dbPath, busyTimeoutMs: 1000 });

add("queued.now", { k: "queued" }, { dedupeKey: "dk-queued", priority: 5 });
add("queued.delayed", { k: "delayed" }, { delayMs: 10 * 365 * 24 * 60 * 60 * 1000 });
add("other.queue", { k: "isolated" }, { queue: "other" });

add("done", { k: "completed" }, { dedupeKey: "dk-done" });
const c = claim("done");
now += 10;
call("settleSuccess", {
  nowMs: now,
  id: c.id,
  workerId: "w-old",
  generation: c.lease_generation,
  resultJson: JSON.stringify({ ok: true, n: 1 }),
});

add("dead", { k: "failed" }, { maxAttempts: 1 });
const f = claim("dead");
now += 10;
call("settleFailure", {
  nowMs: now,
  id: f.id,
  workerId: "w-old",
  generation: f.lease_generation,
  error: { name: "Error", message: "boom" },
  nonRetryable: false,
});

add("retrying", { k: "retrying" }, { backoff: { type: "fixed", delayMs: 5_000 } });
const r = claim("retrying");
now += 10;
call("settleFailure", {
  nowMs: now,
  id: r.id,
  workerId: "w-old",
  generation: r.lease_generation,
  error: { name: "Error", message: "transient" },
  nonRetryable: false,
});

const x = add("cancelme", { k: "cancelled" });
call("cancelQueued", { nowMs: now, id: x.id, queue: "app" });

add("running", { k: "active" }, { attemptTimeoutMs: 1000 });
claim("running");

add("expired", { k: "expired-lease" });
claim("expired", 1_000);

call("close", {});

const db = new DatabaseSync(dbPath);
const lines = [
  "-- Generated by tests/fixtures/v0.1.0/generate.ts from the v0.1.0 tag. Do not edit.",
];
const objects = db
  .prepare(
    "SELECT type, name, sql FROM sqlite_master WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%' ORDER BY CASE type WHEN 'table' THEN 0 ELSE 1 END, rowid",
  )
  .all() as { type: string; name: string; sql: string }[];
for (const o of objects) lines.push(`${o.sql};`);
const quote = (v: unknown) =>
  v === null ? "NULL" : typeof v === "string" ? `'${v.replaceAll("'", "''")}'` : String(v);
for (const o of objects.filter((t) => t.type === "table")) {
  for (const row of db.prepare(`SELECT * FROM ${o.name} ORDER BY rowid`).all()) {
    const rec = row as Record<string, unknown>;
    const cols = Object.keys(rec);
    lines.push(
      `INSERT INTO ${o.name} (${cols.join(", ")}) VALUES (${cols.map((k) => quote(rec[k])).join(", ")});`,
    );
  }
}
db.close();
writeFileSync(out, lines.join("\n") + "\n");
rmSync(dir, { recursive: true, force: true });
console.log(`wrote ${out}`);
